export function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const [, setLocation] = useLocation();
  const isRegister = mode === 'register';
  const [name, setName] = useState('');
  const [businessName, setBusinessName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (isRegister) {
        await registerBusiness({ name, businessName, email, password });
      } else {
        await loginBusiness(email, password);
      }
      setLocation('/dashboard');
    } catch (caught) {
      const code = caught instanceof Error ? caught.message : 'Something went wrong. Please try again.';
      setError(code.includes('auth/invalid-credential') ? 'That email or password is not correct.' : code.replace('Firebase: ', '').split(' (')[0]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="noise grid min-h-[100dvh] bg-[#f7f4eb] text-[#29253e] lg:grid-cols-[.82fr_1.18fr]">
      <div className="relative hidden overflow-hidden bg-[#29253e] p-10 text-[#f8f4e9] lg:flex lg:flex-col lg:justify-between">
        <div className="absolute -right-28 top-20 h-72 w-72 rounded-full bg-[#9e92ec]/30 blur-3xl" />
        <div className="absolute -bottom-16 -left-20 h-64 w-64 rounded-full bg-[#f4a17b]/20 blur-3xl" />
        <Logo light />
        <div className="relative max-w-md">
          <p className="mb-4 font-mono-app text-[10px] uppercase tracking-[.16em] text-[#aaa0f3]">A calmer support layer</p>
          <h1 className="text-5xl font-medium leading-[.98] tracking-[-.06em]">Make every <span className="font-display italic text-[#f4a17b]">question</span> count.</h1>
          <p className="mt-6 max-w-sm text-sm leading-6 text-[#bdb7ca]">Answers that feel human, leads with context, and a workspace that keeps your team in the loop.</p>
        </div>
        <div className="relative flex items-center gap-3 text-xs text-[#aaa5b7]"><span className="grid h-8 w-8 place-items-center rounded-xl bg-[#9e92ec] text-[10px] font-bold text-[#29253e]">dx</span> Support, with a pulse.</div>
      </div>
      <div className="flex min-h-[100dvh] flex-col px-5 py-6 sm:px-10 lg:px-20">
        <div className="flex items-center justify-between lg:hidden"><Logo /><button onClick={() => setLocation('/')} className="text-sm font-semibold text-[#6c6879]">Back home</button></div>
        <div className="mx-auto flex w-full max-w-md flex-1 flex-col justify-center">
          <p className="font-mono-app text-[10px] uppercase tracking-[.16em] text-[#8f7bab]">{isRegister ? 'Start your workspace' : 'Welcome back'}</p>
          <h2 className="mt-3 text-4xl font-medium tracking-[-.055em]">{isRegister ? 'Bring calm to support.' : 'Good to see you again.'}</h2>
          <p className="mt-3 text-sm leading-6 text-[#77727c]">{isRegister ? 'Create your Drexora workspace and get your support widget live in minutes.' : 'Sign in to manage your FAQs, leads, conversations, and widget.'}</p>
          <form onSubmit={submit} className="mt-8 grid gap-4">
            {isRegister && <><label className="grid gap-2 text-sm font-semibold">Your name<input required value={name} onChange={(event) => setName(event.target.value)} className="rounded-xl border border-[#ddd8cf] bg-[#fffdf8] px-3.5 py-3 font-normal outline-none focus:border-[#9e92ec] focus:ring-2 focus:ring-[#9e92ec]/20" /></label><label className="grid gap-2 text-sm font-semibold">Business name<input required value={businessName} onChange={(event) => setBusinessName(event.target.value)} className="rounded-xl border border-[#ddd8cf] bg-[#fffdf8] px-3.5 py-3 font-normal outline-none focus:border-[#9e92ec] focus:ring-2 focus:ring-[#9e92ec]/20" /></label></>}
            <label className="grid gap-2 text-sm font-semibold">Email<input required type="email" value={email} onChange={(event) => setEmail(event.target.value)} className="rounded-xl border border-[#ddd8cf] bg-[#fffdf8] px-3.5 py-3 font-normal outline-none focus:border-[#9e92ec] focus:ring-2 focus:ring-[#9e92ec]/20" /></label>
            <label className="grid gap-2 text-sm font-semibold">Password<input required minLength={6} type="password" value={password} onChange={(event) => setPassword(event.target.value)} className="rounded-xl border border-[#ddd8cf] bg-[#fffdf8] px-3.5 py-3 font-normal outline-none focus:border-[#9e92ec] focus:ring-2 focus:ring-[#9e92ec]/20" /></label>
            {error && <p role="alert" className="rounded-xl bg-[#fae3d9] px-3 py-2.5 text-sm text-[#a45d49]">{error}</p>}
            <Button type="submit" className="mt-2 w-full" variant="primary">{loading ? 'Working…' : isRegister ? 'Create workspace' : 'Sign in'} <ArrowRight size={16} /></Button>
          </form>
          <p className="mt-7 text-center text-sm text-[#77727c]">{isRegister ? 'Already have an account?' : 'New to Drexora?'} <button onClick={() => setLocation(isRegister ? '/login' : '/register')} className="font-semibold text-[#6956a5]">{isRegister ? 'Sign in' : 'Start free'}</button></p>
          {demoMode && <p className="mt-5 text-center text-[11px] text-[#9b969e]">Demo mode is active. Add your Firebase web config to connect this workspace.</p>}
        </div>
      </div>
    </div>
  );
}

function Button({ children, className = '', variant = 'primary', onClick, type = 'button', testId }: { children: ReactNode; className?: string; variant?: 'primary' | 'quiet' | 'outline' | 'accent'; onClick?: () => void; type?: 'button' | 'submit'; testId?: string }) {
  const styles = {
    primary: 'bg-[#29253e] text-[#faf8f1] hover:bg-[#40385e]',
    quiet: 'bg-[#eeeaf4] text-[#39324e] hover:bg-[#e5e0ee]',
    outline: 'border border-[#d8d4df] text-[#39324e] hover:bg-[#f2f0f6]',
    accent: 'bg-[#f4a17b] text-[#35253d] hover:bg-[#f6b18e]',
  };
  return <button type={type} onClick={onClick} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 active:scale-[.98] ${styles[variant]} ${className}`}>{children}</button>;
}

